                            Instructions = "Aqueça leite com canela e casca de limão para infundir aroma; bata gemas com açúcar até clarear e, aos poucos, incorpore o leite quente, mexendo sem parar. Cozinhe em banho-maria até o creme cobrir as costas da colher e resfrie completamente. Na hora de servir, polvilhe uma camada fina de açúcar e queime para formar a crosta caramelizada característica."
                        },
                        new
                        {
                            RecipeId = 61,
                            DishId = 61,
                            Instructions = "Misture farinha de milho com água e sal até formar uma massa maleável; modele discos e cozinhe em chapa ou frigideira até dourarem levemente dos dois lados. Corte as arepas ao meio e recheie com cream cheese ou outro queijo, e, se desejar, peças de carne grelhada. Sirva quentes, aproveitando a textura levemente crocante por fora e macia por dentro."
                        },
                        new
                        {
                            RecipeId = 62,
                            DishId = 62,
                            Instructions = "Deixe o grão-de-bico de molho por algumas horas e cozinhe até ficar macio, ou use grão-de-bico enlatado bem escorrido; processe com alho, cebola, cominho e sal até formar uma massa maleável. Modele bolinhos e frite até ficarem dourados e crocantes por fora. Aqueça pão sírio, recheie com os falafels, adicione tahine, folhas de alface e fatias de tomate; sirva imediatamente para manter contraste de texturas."
                        },
                        new
                        {
                            RecipeId = 63,
                            DishId = 63,
                            Instructions = "Marine tiras de carne em um molho aromático por pelo menos 30 minutos. Grelhe rapidamente até dourarem e monte a baguete crocante com a carne, cebola levemente em conserva (ou crua), coentro fresco e um fio de azeite. Sirva cortado ao meio para preservar crocância do pão e suculência do recheio."
                        },
                        new
                        {
                            RecipeId = 64,
                            DishId = 64,
                            Instructions = "Cozinhe batatas até ficarem macias e amasse; misture com ervilhas cozidas, cebola refogada, especiarias (como cominho e curry em pó) e ajuste sal. Abra porções da massa de farinha, recheie com a mistura e feche formando triângulos; frite em óleo quente até dourar ou asse para versão mais leve. Sirva quente, acompanhando com chutney ou molho picante."
                        },
                        new
                        {
                            RecipeId = 65,
                            DishId = 65,
                            Instructions = "Misture polvilho doce com leite, ovos e queijo coalho ralado até obter uma massa pegajosa; modele pequenas bolinhas e asse ou frite até crescerem e formarem casca leve. Sirva quentes, aproveitando o interior elástico e o sabor salgado do queijo; são ótimas como lanche ou acompanhamento."
                        },
                        new
                        {
                            RecipeId = 66,
                            DishId = 66,
                            Instructions = "Refogue cebola e alho até ficarem translúcidos; acrescente carne moída e cozinhe até dourar, temperando com páprica, sal e pimenta. Recheie discos de massa folhada com a carne refogada, feche bem e asse até dourarem. Sirva quentes, como lanche prático e saboroso de rua."
                        },
                        new
                        {
                            RecipeId = 67,
                            DishId = 67,
                            Instructions = "Tempere a carne em tiras com especiarias e deixe marinar brevemente; grelhe em fogo alto até selar e ficar suculenta. Aqueça o pão sírio e recheie com a carne fatiada, cebola, tahine e folhas frescas, enrolando ou dobrando para servir. A combinação de carne bem temperada e molho cremoso cria o clássico sabor do shawarma."
                        },
                        new
                        {
                            RecipeId = 68,
                            DishId = 68,
                            Instructions = "Prepare uma massa simples com farinha, água, ovo e manteiga; cozinhe rapidamente em panela até formar uma pasta e molde tiras compridas. Frite em óleo quente até dourar e escorra em papel; passe no açúcar misturado com canela enquanto ainda estiverem quentes. Sirva com molho de chocolate quente para mergulhar."
                        },
                        new
                        {
                            RecipeId = 69,
                            DishId = 69,
                            Instructions = "Misture farinha com leite, ovo e um pouco de fermento (se disponível) até formar uma massa macia; modele bolinhos ou discos e cozinhe no vapor até crescerem e ficarem macios. Corte ao meio e recheie com carne grelhada, vegetais em conserva e molhos à escolha; sirva quente para aproveitar a textura aerada do bao."
                        },
                        new
                        {
                            RecipeId = 70,
                            DishId = 70,
                            Instructions = "Misture farinha de milho com água e sal até obter massa maleável; abra discos e recheie com uma mistura de feijão refrito e queijo coalho ralado, fechando e moldando. Grelhe os pupusas em chapa até dourar ambos os lados e o recheio aquecer; sirva quente com curtido e molho de tomate ou pimenta para equilibrar os sabores."
                        },
                        new
                        {
                            RecipeId = 71,
                            DishId = 71,
                            Instructions = "Corte tomates e pepino em cubos regulares; fatie a cebola finamente. Em uma tigela grande, misture os tomates, pepino, cebola, azeitonas e pedaços generosos de queijo feta. Tempere com suco de limão fresco, bastante azeite de oliva, orégãos secos, sal e pimenta. Misture delicadamente, ajuste os temperos e sirva imediatamente para manter a textura crocante dos vegetais."
                        },
                        new
                        {
                            RecipeId = 72,
                            DishId = 72,
                            Instructions = "Aqueça azeite em uma frigideira larga e refogue cebola e alho até ficarem translúcidos. Adicione pimentões picados e deixe murchar; junte tomates (frescos ou molho de tomate), tempere com sal, pimenta e pimenta dedo-de-moça a gosto e cozinhe em fogo médio até formar um molho espesso. Faça pequenos poços no molho e quebre ovos por cima; tampe e cozinhe até as claras firmarem e as gemas ficarem ao ponto desejado. Polvilhe salsinha por cima e sirva com pão."
                        },
                        new
                        {
                            RecipeId = 73,
                            DishId = 73,
                            Instructions = "Corte berinjelas ao meio, faça cortes superficiais na polpa, pincele com azeite e grelhe até ficarem macias e com marcas de grelha. Enquanto isso, misture tahine com suco de limão, um pouco de água para ajustar a textura, alho picado e sal. Regue as berinjelas grelhadas com o molho de tahine, finalize com salsinha picada, um fio de azeite e pimenta moída. Sirva morno ou à temperatura ambiente."
                        },
                        new
                        {
                            RecipeId = 74,
                            DishId = 74,
                            Instructions = "Tempere os peitos de frango com suco de limão, alho picado, azeite, ramos de alecrim e tomilho, sal e pimenta; deixe marinar por ao menos 30 minutos. Pré-aqueça o forno e asse o frango até dourar e atingir temperatura interna adequada, regando ocasionalmente com a marinada. Deixe repousar alguns minutos antes de fatiar; sirva com batatas ou salada e regue com o molho formado durante o cozimento."
                        },
                        new
                        {
                            RecipeId = 75,
                            DishId = 75,
                            Instructions = "Lave bem os mexilhões e descarte os que estiverem abertos. Em uma panela larga, aqueça azeite e refogue alho e cebola até ficarem translúcidos; acrescente tomates picados e vinho branco, deixe reduzir levemente. Junte os mexilhões, tampe e cozinhe até abrirem (descartar os que não abrirem). Finalize com salsinha picada e sirva com fatias de pão para molhar no caldo aromático."
                        },
                        new
                        {
                            RecipeId = 76,
                            DishId = 76,
                            Instructions = "Escorra e cozinhe grão-de-bico até ficar macio (ou use enlatado bem escorrido). Processe o grão-de-bico com tahine, suco de limão, alho, sal e um fio generoso de azeite até obter uma pasta lisa; ajuste a textura com água se necessário. Sirva o hummus regado com azeite extra e acompanhe com pão sírio aquecido e fatias de pepino para frescor."
                        },
                        new
                        {
                            RecipeId = 77,
                            DishId = 77,
                            Instructions = "No processador, junte azeitonas sem caroço, alcaparras, alho, salsinha e um fio de azeite; pulse até obter uma pasta rústica. Ajuste sal e acidez se necessário. Fatie a baguete, torre levemente e espalhe a tapenade sobre as fatias antes de servir como aperitivo."
                        },
                        new
                        {
                            RecipeId = 78,
                            DishId = 78,
                            Instructions = "Coloque um bloco de queijo feta em uma travessa pequena, disponha tomates cortados ao redor e regue tudo com azeite, alho fatiado e orégãos. Leve ao forno pré-aquecido até os tomates murcharem levemente e o feta aquecer; sirva quente com fatias de baguette para acompanhar e molhar no suco formado."
                        },
                        new
                        {
                            RecipeId = 79,
                            DishId = 79,
                            Instructions = "Corte batatas em pedaços médios e tempere com suco de limão, azeite, alho picado, orégãos secos, alecrim, sal e pimenta. Asse em forno quente até ficarem douradas e crocantes por fora, macias por dentro. Sirva imediatamente, finalizando com mais ervas frescas se desejar."
                        },
                        new
                        {
                            RecipeId = 80,
                            DishId = 80,
                            Instructions = "Cozinhe bulgur conforme instruções até ficar macio; misture com tomate picado, cebola refogada, salsinha, azeite e pedaços de queijo feta. Recheie pimentões limpos com essa mistura, disponha em um refratário, regue com um fio de azeite e asse até os pimentões ficarem macios e o recheio aquecer. Sirva quente como prato principal leve."
                        },
                        new
                        {
                            RecipeId = 81,
                            DishId = 81,
                            Instructions = "Refogue cebola e alho em azeite até amaciarem; adicione tomates picados, pasta de tomate e especiarias, deixando o molho apurar. Junte arroz lavado e caldo quente, misture bem e acrescente pedaços de frango previamente dourados. Cozinhe em fogo médio-baixo, mexendo ocasionalmente, até o arroz absorver os sabores e ficar macio. Ajuste sal e pimenta e sirva com folhas frescas e fatias de limão ao lado."
                        },
                        new
                        {
                            RecipeId = 82,
                            DishId = 82,
                            Instructions = "Misture carne moída com cebola picada, alho, curry em pó, pimenta e um pouco de açúcar; coloque em uma travessa untada. Por cima, bata ovos com leite e despeje sobre a carne. Asse em forno médio até a cobertura firmar e dourar levemente. Sirva morno, tradicionalmente acompanhado de arroz e chutney de frutas quando disponível."
                        },
                        new
                        {
                            RecipeId = 83,
                            DishId = 83,
                            Instructions = "Corte a carne em tiras finas e tempere com uma mistura de amendoim moído, alho, pimenta e sal; deixe absorver os temperos por pelo menos 30 minutos. Espete as tiras em palitos e grelhe em fogo alto até desenvolver crostas douradas. Sirva com fatias de cebola e rodelas de pepino para refrescar entre as mordidas."
                        },
                        new
                        {
                            RecipeId = 84,
                            DishId = 84,
                            Instructions = "Sele a carne em panela ampla, retire e refogue cebola, alho e pimentões até amaciarem. Acrescente tomates, caldo e especiarias (açafrão, cominho), devolva a carne e cozinhe em fogo baixo até ficar macia e o molho reduzir. Finalize com ervas frescas e sirva com cuscuz ou pão para aproveitar o molho."
                        },
                        new
                        {
                            RecipeId = 85,
                            DishId = 85,
                            Instructions = "Marine pedaços de frango com suco de limão, alho, pimenta e sal por algumas horas. Refogue uma grande quantidade de cebola até caramelizar levemente, acrescente o frango e cozinhe lentamente no líquido da marinada até ficar suculento e com sabor equilibrado entre ácido e caramelizado. Sirva com arroz ou cuscuz."
                        },
                        new
                        {
                            RecipeId = 86,
                            DishId = 86,
                            Instructions = "Tempere camarões limpos com pimenta, alho picado e suco de limão; deixe marinar brevemente. Aqueça azeite em frigideira, frite os camarões rapidamente até ficarem opacos e ligeiramente dourados, regando com a marinada reduzida. Sirva com mais limão e pão para molhar no molho picante."
                        },
                        new
                        {
                            RecipeId = 87,
                            DishId = 87,
                            Instructions = "Misture farinha, açúcar, ovo, leite de coco e uma pitada de fermento (se disponível) formando uma massa levemente pegajosa. Modele em porções e frite em óleo quente até dourarem por fora e cozinharem por dentro. Polvilhe açúcar e sirva quentes, acompanhados de chá ou café."
                        },
                        new
                        {
                            RecipeId = 88,
                            DishId = 88,
                            Instructions = "Misture farinha de milho com água quente e sal, mexendo até obter uma papa espessa e lisa; cozinhe por alguns minutos, mexendo, até o ponto desejado. Sirva quente com um fio de manteiga ou acompanhando um ensopado rico para absorver o molho."
                        },
                        new
                        {
                            RecipeId = 89,
                            DishId = 89,
                            Instructions = "Cozinhe arroz até ficar macio e reserve. Cozinhe grão-de-bico até amaciar. Cozinhe macarrão curto separadamente. Prepare um molho de tomate bem temperado com alho e cebola e ajuste o picante. Monte camadas com arroz, macarrão e grão-de-bico, regando com o molho de tomate e finalizando com cebolas crocantes. Sirva quente, permitindo que cada porção receba molho generoso."
                        },
                        new
                        {
                            RecipeId = 90,
                            DishId = 90,
                            Instructions = "Corte uma baguete e retire parte do miolo formando uma cavidade; prepare um curry espesso com carne refogada, tomate e especiarias até reduzir bem. Recheie o pão com o curry quente e sirva imediatamente, acompanhando com arroz ou salada se desejar."
                        },
                        new
                        {
                            RecipeId = 91,
                            DishId = 91,
                            Instructions = "Prepare uma massa leve de cerveja ou tempêra (farinha, água/gás, ovo) e tempere o filé de peixe. Corte batatas em palitos regulares e seque bem. Frite as batatas até dourar e reserve. Passe o peixe na massa e frite em óleo quente até a crosta ficar dourada. Sirva o peixe com as batatas, polvilhe sal e ofereça vinagre à parte; sirva quente para manter a crocância."
                        },
                        new
                        {
                            RecipeId = 92,
                            DishId = 92,
                            Instructions = "Pique e cozinhe uma grande quantidade de cebolas em fogo baixo até caramelizarem; junte manteiga clarificada e alho. Adicione pedaços de frango e a mistura de berbere, mexendo para cobrir bem; acrescente caldo e cozinhe lentamente até o frango ficar macio e o molho espesso. Cozinhe ovos até o ponto desejado e sirva por cima, decorando com um fio de azeite e fatias de pão injera se quiser uma apresentação tradicional."
                        },
                        new
                        {
                            RecipeId = 93,
                            DishId = 93,
                            Instructions = "Marine pedaços de frango com uma mistura de allspice, pimenta, alho, cebola, suco de limão e óleo; deixe marinar por algumas horas. Grelhe em fogo médio-alto até o exterior ficar levemente carbonizado e o interior cozido. Regue com suco de limão extra ao servir e acompanhe com arroz, salada e molhos à base de iogurte para equilibrar o picante."
                        },
                        new
                        {
                            RecipeId = 94,
                            DishId = 94,
                            Instructions = "Prepare uma massa de pão relativamente macia com farinha, água, leite e fermento; abra em disco e recheie generosamente com queijo sulguni ralado. Dobre as bordas formando um barco e asse em forno quente até o queijo borbulhar; no final, quebre um ovo no centro e asse rapidamente até a clara firmar. Sirva quente e corte em fatias para compartilhar."
                        },
                        new
                        {
                            RecipeId = 95,
                            DishId = 95,
                            Instructions = "Marine pedaços de carne ou frango em uma mistura de molho de soja, vinagre e alho por pelo menos 30 minutos. Refogue alho e cebola, junte a carne com a marinada e cozinhe em fogo baixo até o líquido reduzir e os sabores ficarem concentrados. Sirva com arroz e um pouco de cebolinha picada por cima para frescor."
                        },
                        new
                        {
                            RecipeId = 96,
                            DishId = 96,
                            Instructions = "Doure cebola e alho em azeite, acrescente nozes trituradas e deixe tostar levemente; junte pedaços de frango e cubra com caldo. Adicione molho de romã e cozinhe em fogo baixo até o molho engrossar e as nozes estiverem integradas, formando uma textura aveludada. Ajuste sal e acidez e sirva com arroz basmati solto."
                        },
                        new
                        {
                            RecipeId = 97,
                            DishId = 97,
                            Instructions = "Cozinhe batatas e amasse até ficarem lisas; misture com queijo (ou cream cheese), tempere e use como recheio. Prepare uma massa com farinha, ovo e água, abra, corte discos e recheie com uma porção do recheio; feche bem e cozinhe em água fervente até subirem. Opcional: doure na manteiga antes de servir para textura adicional."
                        },
                        new
                        {
                            RecipeId = 98,
                            DishId = 98,
                            Instructions = "Tempere cubos de peixe cru com molho de soja, óleo de gergelim, suco de limão e sementes de gergelim; deixe marinar por alguns minutos. Monte tigelas com arroz de sushi, coloque o peixe marinado por cima e adicione complementos como pepino fatiado, algas, abacate e cebolinha. Finalize com sementes de gergelim e um fio de molho adicional se desejar."
                        },
                        new
                        {
                            RecipeId = 99,
                            DishId = 99,
                            Instructions = "Pré-aqueça o forno. Forre forminhas com massa folhada e reserve. Em uma panela, aqueça leite com baunilha; bata gemas com açúcar até clarear e incorpore o leite quente aos poucos. Coe e despeje o creme nas forminhas forradas. Asse em forno quente até o topo caramelizar levemente; deixe esfriar antes de desenformar e polvilhe canela a gosto."
                        },
                        new
                        {
                            RecipeId = 100,
                            DishId = 100,
                            Instructions = "Cozinhe mandioca (ou farinha de mandioca/cuscuz) até formar uma papa firme e maleável (fufu). Para o ensopado, refogue cebola e alho, acrescente carne e cozinhe; junte pasta de amendoim e caldo, cozinhe até o molho ficar espesso e bem temperado. Sirva porções do fufu com o guisado de amendoim por cima, permitindo que cada pessoa molde o fufu e pegue o molho com a mão."
                        });
